using System; using System.Linq; using System.Web.Http; using GiveAID.Web.Data; using GiveAID.Web.Helpers; using GiveAID.Web.Models;  namespace GiveAID.Web.Controllers {     /// <summary>     /// Gallery ΓÇö photo/image management.     /// Stores photo URLs (no file upload). Supports optional Programme linkage.     /// </summary>     [RoutePrefix("api/gallery")]     public class GalleryController : ApiController     {         private readonly GiveAIDContext _context;          public GalleryController()         {             _context = new GiveAIDContext();         }          // GET: api/gallery         // Public ΓÇö list gallery items with optional filters         [HttpGet]         [Route("")]         public IHttpActionResult GetAll(             bool featuredOnly = false,             string category = null,             int? programmeId = null,             int page = 1,             int pageSize = 24)         {             try             {                 var query = _context.Gallery.AsQueryable();                  if (featuredOnly)                 {                     query = query.Where(g => g.IsFeatured);                 }                  if (!string.IsNullOrEmpty(category))                 {                     query = query.Where(g => g.Category == category);                 }                  if (programmeId.HasValue)                 {                     query = query.Where(g => g.ProgrammeId == programmeId.Value);                 }                  var total = query.Count();                  var items = query                     .OrderByDescending(g => g.IsFeatured)                     .ThenBy(g => g.DisplayOrder)                     .ThenByDescending(g => g.UploadedAt)                     .Skip((page - 1) * pageSize)                     .Take(pageSize)                     .ToList()                     .Select(g => new                     {                         galleryId = g.GalleryId,                         title = g.Title,                         photoUrl = g.PhotoUrl,                         thumbnailUrl = g.ThumbnailUrl ?? g.PhotoUrl,                         category = g.Category,                         tags = g.Tags,                         programmeId = g.ProgrammeId,                         organizationId = g.OrganizationId,                         isFeatured = g.IsFeatured,                         displayOrder = g.DisplayOrder,                         uploadedAt = g.UploadedAt                     });                  return Ok(new ApiResponse                 {                     Success = true,                     Data = new                     {                         items,                         pagination = new                         {                             total,                             page,                             pageSize,                             totalPages = (int)Math.Ceiling((double)total / pageSize)                         }                     }                 });             }             catch (Exception ex)             {                 return InternalServerError(ex);             }         }          // GET: api/gallery/categories         // Public ΓÇö distinct categories         [HttpGet]         [Route("categories")]         public IHttpActionResult GetCategories()         {             try             {                 var categories = _context.Gallery                     .Where(g => !string.IsNullOrEmpty(g.Category))                     .Select(g => g.Category)                     .Distinct()                     .OrderBy(c => c)                     .ToList();                  return Ok(new ApiResponse                 {                     Success = true,                     Data = categories                 });             }             catch (Exception ex)             {                 return InternalServerError(ex);             }         }          // GET: api/gallery/programmes         // Public ΓÇö programmes that have gallery items         [HttpGet]         [Route("programmes")]         public IHttpActionResult GetProgrammes()         {             try             {                 var programmes = _context.Gallery                     .Where(g => g.ProgrammeId.HasValue)                     .Select(g => g.ProgrammeId.Value)                     .Distinct()                     .ToList()                     .Select(pid =>                     {                         var p = _context.Programmes.Find(pid);                         return p != null ? new                         {                             programmeId = p.ProgrammeId,                             title = p.Title,                             imageUrl = p.ImageUrl,                             startDate = p.StartDate                         } : null;                     })                     .Where(p => p != null)                     .OrderBy(p => p.title)                     .ToList();                  return Ok(new ApiResponse                 {                     Success = true,                     Data = programmes                 });             }             catch (Exception ex)             {                 return InternalServerError(ex);             }         }          // GET: api/gallery/5         [HttpGet]         [Route("{id:int}")]         public IHttpActionResult GetById(int id)         {             try             {                 var item = _context.Gallery.Find(id);                 if (item == null)                 {                     return NotFound();                 }                  string programmeName = null;                 string organizationName = null;                  if (item.ProgrammeId.HasValue)                 {                     var prog = _context.Programmes.Find(item.ProgrammeId.Value);                     programmeName = prog?.Title;                 }                 if (item.OrganizationId.HasValue)                 {                     var org = _context.Organizations.Find(item.OrganizationId.Value);                     organizationName = org?.OrganizationName;                 }                  return Ok(new ApiResponse                 {                     Success = true,                     Data = new                     {                         galleryId = item.GalleryId,                         title = item.Title,                         photoUrl = item.PhotoUrl,                         thumbnailUrl = item.ThumbnailUrl ?? item.PhotoUrl,                         category = item.Category,                         tags = item.Tags,                         programmeId = item.ProgrammeId,                         programmeName = programmeName,                         organizationId = item.OrganizationId,                         organizationName = organizationName,                         isFeatured = item.IsFeatured,                         displayOrder = item.DisplayOrder,                         uploadedAt = item.UploadedAt                     }                 });             }             catch (Exception ex)             {                 return InternalServerError(ex);             }         }          // POST: api/gallery  (Admin only)         [HttpPost]         [Route("")]         [Authorize(Roles = "SuperAdmin,Admin")]         public IHttpActionResult Create(GalleryRequest request)         {             try             {                 if (request == null ||                     string.IsNullOrWhiteSpace(request.PhotoUrl))                 {                     return BadRequest("Photo URL is required.");                 }                  if (!string.IsNullOrEmpty(request.PhotoUrl) &&                     !request.PhotoUrl.StartsWith("http", StringComparison.OrdinalIgnoreCase))                 {                     return BadRequest("Photo URL must be a valid HTTP/HTTPS URL.");                 }                  if (request.ProgrammeId.HasValue)                 {                     var prog = _context.Programmes.Find(request.ProgrammeId.Value);                     if (prog == null)                     {                         return BadRequest("Programme not found.");                     }                 }                  var userId = JwtHelper.GetUserIdFromToken(Request);                  var item = new Gallery                 {                     Title = request.Title?.Trim(),                     PhotoUrl = request.PhotoUrl.Trim(),                     ThumbnailUrl = request.ThumbnailUrl?.Trim(),                     Category = request.Category?.Trim(),                     Tags = request.Tags?.Trim(),                     ProgrammeId = request.ProgrammeId,                     OrganizationId = request.OrganizationId,                     IsFeatured = request.IsFeatured,                     DisplayOrder = request.DisplayOrder,                     UploadedBy = userId,                     UploadedAt = DateTime.Now                 };                  _context.Gallery.Add(item);                 _context.SaveChanges();                  return Ok(new ApiResponse                 {                     Success = true,                     Message = "Gallery item added successfully.",                     Data = new { galleryId = item.GalleryId, title = item.Title }                 });             }             catch (Exception ex)             {                 return InternalServerError(ex);             }         }          // PUT: api/gallery/5  (Admin only)         [HttpPut]         [Route("{id:int}")]         [Authorize(Roles = "SuperAdmin,Admin")]         public IHttpActionResult Update(int id, GalleryRequest request)         {             try             {                 var item = _context.Gallery.Find(id);                 if (item == null)                 {                     return NotFound();                 }                  if (!string.IsNullOrEmpty(request.PhotoUrl) &&                     !request.PhotoUrl.StartsWith("http", StringComparison.OrdinalIgnoreCase))                 {                     return BadRequest("Photo URL must be a valid HTTP/HTTPS URL.");                 }                  if (request.ProgrammeId.HasValue)                 {                     var prog = _context.Programmes.Find(request.ProgrammeId.Value);                     if (prog == null)                     {                         return BadRequest("Programme not found.");                     }                 }                  item.Title = request.Title?.Trim();                 item.PhotoUrl = !string.IsNullOrWhiteSpace(request.PhotoUrl)                     ? request.PhotoUrl.Trim()                     : item.PhotoUrl;                 item.ThumbnailUrl = request.ThumbnailUrl?.Trim();                 item.Category = request.Category?.Trim();                 item.Tags = request.Tags?.Trim();                 item.ProgrammeId = request.ProgrammeId;                 item.OrganizationId = request.OrganizationId;                 item.IsFeatured = request.IsFeatured;                 item.DisplayOrder = request.DisplayOrder;                  _context.SaveChanges();                  return Ok(new ApiResponse                 {                     Success = true,                     Message = "Gallery item updated successfully."                 });             }             catch (Exception ex)             {                 return InternalServerError(ex);             }         }          // DELETE: api/gallery/5  (SuperAdmin only)         [HttpDelete]         [Route("{id:int}")]         [Authorize(Roles = "SuperAdmin")]         public IHttpActionResult Delete(int id)         {             try             {                 var item = _context.Gallery.Find(id);                 if (item == null)                 {                     return NotFound();                 }                  _context.Gallery.Remove(item);                 _context.SaveChanges();                  return Ok(new ApiResponse                 {                     Success = true,                     Message = "Gallery item deleted successfully."                 });             }             catch (Exception ex)             {                 return InternalServerError(ex);             }         }          protected override void Dispose(bool disposing)         {             if (disposing)             {                 _context.Dispose();             }             base.Dispose(disposing);         }     }      public class GalleryRequest     {         public string Title { get; set; }         public string PhotoUrl { get; set; }         public string ThumbnailUrl { get; set; }         public string Category { get; set; }         public string Tags { get; set; }         public int? ProgrammeId { get; set; }         public int? OrganizationId { get; set; }         public bool IsFeatured { get; set; }         public int DisplayOrder { get; set; }     } }